// Builds manuscript/FINAL_INTEGRATED_MANUSCRIPT.docx
// Sources: Suganth's draft (Manuscript_Meiotic_HPV_HNSCC_revised_main.pdf / .doc) for the panel,
// methylation, validation and single-cell analyses; canonical repository outputs for the TCGA
// differential-expression, enrichment, immune-deconvolution and survival analyses.
// Requires the `docx` npm package.
const fs = require("fs");
const path = require("path");
const {
  Document, Packer, Paragraph, TextRun, HeadingLevel, ImageRun, Table, TableRow, TableCell,
  WidthType, AlignmentType, BorderStyle, ShadingType, Footer, PageNumber, PageOrientation,
} = require("docx");

const REPO = process.env.REPO_DIR || path.resolve(__dirname, "..");
const FIG = (p) => path.join(REPO, p);
const CONTENT_W = 9638; // A4 portrait minus 2 cm margins, DXA

// ---------- gene-symbol italics ----------
const GENES = ["LOC375196","STAG3","SMC1B","ZFR2","RAD9B","TDRD10","CNTD1","SYCP2","MAJIN","C11orf85","SYCE2","MEI1","TAF7L","GBX1","GRIN2C","ABCA17P","PRDM15","DSC1","MUCL1","SPRR4","KRTDAP","KRT1","KRT14","KRT16","KRT6A","S100A7","IGKC","IGHA1","IGHM","MS4A1","CD79A","CD79B","IGHG1","IGHG3","CD8A","CD8B","LINC02700","AL033397\\.1","FOLR3","RDH12","SLC3A2","IGFL3","SLC35F3","MKI67","PCNA","TOP2A","CCNB1","BUB1","AURKA"];
const GENE_RE = new RegExp("(?<![A-Za-z0-9/.-])(" + GENES.join("|") + ")(?![A-Za-z0-9])", "g");
let ITALIC_GENES = true;
function plain(text, base) {
  if (!ITALIC_GENES || base.italics) return [new TextRun({ text, ...base })];
  const out = []; let last = 0, m; GENE_RE.lastIndex = 0;
  while ((m = GENE_RE.exec(text)) !== null) {
    if (m.index > last) out.push(new TextRun({ text: text.slice(last, m.index), ...base }));
    out.push(new TextRun({ text: m[0], ...base, italics: true }));
    last = m.index + m[0].length;
  }
  if (last < text.length) out.push(new TextRun({ text: text.slice(last), ...base }));
  return out;
}

// ---------- numbered citations, in order of first appearance ----------
const CITE = new Map();
function cite(text) {
  return text.replace(/\[(https:\/\/doi\.org\/[^\]]+)\]/g, (_, inner) => {
    const nums = inner.split(/;\s*/).map((u) => {
      const doi = u.trim().replace("https://doi.org/", "").toLowerCase();
      if (!CITE.has(doi)) CITE.set(doi, CITE.size + 1);
      return CITE.get(doi);
    }).sort((a, b) => a - b);
    const parts = []; let i = 0;
    while (i < nums.length) { let j = i; while (j + 1 < nums.length && nums[j + 1] === nums[j] + 1) j++;
      parts.push(j - i >= 2 ? `${nums[i]}–${nums[j]}` : nums.slice(i, j + 1).join(", ")); i = j + 1; }
    return `[${parts.join(", ")}]`;
  });
}

// ---------- supplementary items numbered in order of first citation ----------
// In text write {ST:key} for a supplementary table and {SF:key} for a supplementary figure.
const ST = new Map(), SF = new Map();
function supp(text) {
  return text.replace(/\{(ST|SF):([a-z0-9_]+)\}/g, (_, kind, key) => {
    const m = kind === "ST" ? ST : SF;
    if (!m.has(key)) m.set(key, m.size + 1);
    return `S${m.get(key)}`;
  });
}

function runs(text, base = {}) {
  text = cite(supp(text));
  const out = [];
  const re = /(\*\*[^*]+\*\*|\*[^*]+\*|\^[^^]+\^|~[^~]+~)/g;
  let last = 0, m;
  while ((m = re.exec(text)) !== null) {
    if (m.index > last) out.push(...plain(text.slice(last, m.index), base));
    const t = m[0];
    if (t.startsWith("**")) out.push(...plain(t.slice(2, -2), { bold: true, ...base }));
    else if (t.startsWith("*")) out.push(new TextRun({ text: t.slice(1, -1), italics: true, ...base }));
    else if (t.startsWith("~")) out.push(new TextRun({ text: t.slice(1, -1), subScript: true, ...base }));
    else out.push(new TextRun({ text: t.slice(1, -1), superScript: true, ...base }));
    last = m.index + t.length;
  }
  if (last < text.length) out.push(...plain(text.slice(last), base));
  return out;
}
const P = (t, o = {}) => new Paragraph({ children: runs(t), spacing: { after: 140, line: 288 }, ...o });
const H1 = (t) => new Paragraph({ text: t, heading: HeadingLevel.HEADING_1, spacing: { before: 280, after: 140 } });
const H2 = (t) => new Paragraph({ text: t, heading: HeadingLevel.HEADING_2, spacing: { before: 200, after: 100 }, keepNext: true });
const CAP = (t) => new Paragraph({ children: runs(t, { size: 18 }), spacing: { after: 220, line: 260 } });

function pngSize(file) {
  const b = fs.readFileSync(file);
  return { w: b.readUInt32BE(16), h: b.readUInt32BE(20), data: b };
}
// landscape figures are placed in their own landscape section
const LANDSCAPE = { __section: "landscape" }, PORTRAIT = { __section: "portrait" };
function FIGURE(rel, caption, widthPx = 640, landscape = false) {
  const { w, h, data } = pngSize(FIG(rel));
  const height = Math.round((widthPx * h) / w);
  const block = [
    new Paragraph({ alignment: AlignmentType.CENTER, keepNext: true, spacing: { before: 120, after: 80 },
      children: [new ImageRun({ type: "png", data, transformation: { width: widthPx, height } })] }),
    CAP(caption),
  ];
  return landscape ? [LANDSCAPE, ...block, PORTRAIT] : block;
}

const border = { style: BorderStyle.SINGLE, size: 4, color: "999999" };
const borders = { top: border, bottom: border, left: border, right: border };
function TABLE(headers, rows, widths) {
  const total = widths.reduce((a, b) => a + b, 0);
  const W = widths.map((x) => Math.floor((x * CONTENT_W) / total));
  W[W.length - 1] += CONTENT_W - W.reduce((a, b) => a + b, 0);
  const cell = (t, i, head) => new TableCell({
    borders, width: { size: W[i], type: WidthType.DXA },
    shading: head ? { fill: "E8EEF4", type: ShadingType.CLEAR, color: "auto" } : undefined,
    margins: { top: 50, bottom: 50, left: 90, right: 90 },
    children: [new Paragraph({ children: runs(String(t), { size: 17, bold: !!head }) })],
  });
  return new Table({
    width: { size: CONTENT_W, type: WidthType.DXA }, columnWidths: W,
    rows: [new TableRow({ tableHeader: true, children: headers.map((h, i) => cell(h, i, true)) }),
      ...rows.map((r) => new TableRow({ cantSplit: true, children: r.map((c, i) => cell(c, i, false)) }))],
  });
}
const TCAP = (t) => new Paragraph({ children: runs(t, { size: 18 }), keepNext: true, spacing: { before: 200, after: 80 } });

const SD = "figures/integrated/composed/";

// ======================================================================
const body = [];
const add = (...x) => x.flat().forEach((e) => body.push(e));

add(new Paragraph({ alignment: AlignmentType.CENTER, spacing: { after: 300 }, children: [new TextRun({
  text: "Transcriptionally active HPV-positive head and neck squamous cell carcinoma is associated with a coordinated meiotic gene programme and promoter hypomethylation",
  bold: true, size: 30 })] }));

// ---------------- ABSTRACT ----------------
add(H1("Abstract"));
add(P("**Background.** Human papillomavirus-positive (HPV+) head and neck squamous cell carcinoma (HNSCC) differs from HPV− disease in its methylome and its immune microenvironment. Germ-cell gene expression in tumours is usually attributed to stochastic de-repression of cancer–testis antigens (CTAs). We asked whether meiotic gene expression in HPV+ HNSCC instead forms a specific, coordinated programme, and where in the tumour it resides."));
add(P("**Methods.** Differential expression and enrichment analyses of 279 TCGA-HNSC tumours (36 HPV+) identified meiosis as a dominant HPV-associated theme. A 95-gene panel of the meiotic machinery, with the classic MAGE/CTAG antigens as a comparator, was tested for promoter methylation in TCGA (n = 125), validated in GSE65858 (n = 256), which records HPV DNA status and viral transcriptional activity separately, and replicated for methylation in GSE38266 (n = 42). Immune composition was estimated with CIBERSORTx, and two single-cell RNA-seq cohorts (35 tumours) were used to localise the signal."));
add(P("**Results.** Meiotic gene categories, but not the MAGE/CTAG family, were enriched among HPV+-upregulated genes (odds ratio 10.9). Eighteen of 49 panel promoters were hypomethylated in HPV+ tumours, and hypomethylation correlated with meiotic expression (ρ = −0.755). A six-gene core meiotic score separated transcriptionally active HPV+ tumours from HPV− tumours (AUC = 0.959, 95% CI 0.91–1.00), whereas HPV DNA-positive, transcriptionally silent tumours did not differ detectably from HPV− tumours (P = 0.56); MAGE/CTAG antigens performed at chance (AUC = 0.411, 95% CI 0.31–0.51). The core genes were co-expressed as a module only in HPV+ tumours (mean ρ = 0.556 vs 0.149), and methylation differences replicated across cohorts (ρ = 0.688). HPV+ tumours had more plasma cells and CD8+ T cells, yet at single-cell resolution the core score differed by HPV status only in malignant cells (Δ = 0.103 vs ≤ 0.011 in non-malignant cell types). The malignant-cell signal replicated in a second cohort (AUC = 0.945, 95% CI 0.83–1.00) and was attenuated by 22% after adjustment for proliferation."));
add(P("**Conclusions.** Transcriptionally active HPV+ HNSCC is associated with a coordinated meiotic gene programme in malignant cells, accompanied by promoter hypomethylation, whereas the classic cancer–testis antigens show none of these features. The meiotic machinery, rather than the broader cancer–testis antigen repertoire, is the more specific germ-cell feature of HPV-driven HNSCC."));
add(P("**Keywords:** Human papillomavirus · Head and neck squamous cell carcinoma · DNA methylation · Meiosis · Cancer–testis antigens · Synaptonemal complex · Meiotic cohesin · Tumour immune microenvironment"));

// ---------------- INTRODUCTION ----------------
add(H1("1. Introduction"));
add(P("Head and neck squamous cell carcinoma (HNSCC) is the sixth most common cancer worldwide, with roughly 900,000 new cases and 450,000 deaths annually [https://doi.org/10.3322/caac.21660]. Within it, tumours associated with human papillomavirus (HPV) infection have risen steeply in incidence over the past three decades, particularly in the oropharynx and in younger patients without the tobacco and alcohol exposure that characterises the classical disease [https://doi.org/10.1200/JCO.2011.36.4596]. HPV+ HNSCC is now recognised as a disease entity distinct from its HPV− counterpart, with a different mutational landscape, a characteristic transcriptional profile and a markedly better prognosis [https://doi.org/10.1038/nature14129; https://doi.org/10.1056/NEJMoa0912217; https://doi.org/10.1038/nrc.2018.11]. The prognostic difference is large enough to have changed staging and to have motivated de-escalation trials [https://doi.org/10.1038/s41571-022-00603-7], yet its mechanistic basis is only partly understood, and HPV+ patients who nonetheless relapse cannot currently be identified from viral status alone."));
add(P("The proximate cause of the difference is viral. The E6 and E7 oncoproteins inactivate p53 and RB, respectively, and in doing so restructure the host cell rather than simply disabling two checkpoints: E7 releases E2F-driven transcription and drives the p16 accumulation used clinically as a surrogate marker, and both proteins engage chromatin-modifying complexes [https://doi.org/10.1038/nrc2886]. A substantial part of the resulting distinction is therefore epigenetic. HPV+ tumours carry a reproducible methylation signature [https://doi.org/10.1186/s13073-017-0419-z], E7 can drive locus-specific promoter methylation changes [https://doi.org/10.1111/cas.12761], and both hypermethylation and hypomethylation events have been catalogued in this setting [https://doi.org/10.1186/gm419; https://doi.org/10.5858/arpa.2014-0554-RA; https://doi.org/10.1016/j.omtn.2022.11.012]. Viral DNA can, however, be present without ongoing viral transcription, and integration status and transcriptional activity are not equivalent [https://doi.org/10.1073/pnas.1416074111; https://doi.org/10.1002/ijc.29649], a distinction that any claim of a virus-driven host programme has to address."));
add(P("HPV+ and HPV− tumours also differ in cellular composition. HPV+ tumours generally show a more immunologically active microenvironment with greater lymphocytic infiltration, which has been linked to their favourable prognosis [https://doi.org/10.1038/nrc.2018.11]. This compartment matters here in two ways: it is part of the biology that distinguishes the two diseases, and it is the main alternative explanation for any expression difference measured in bulk tissue, because a shift in cell proportions can resemble a change of state within tumour cells."));
add(P("Against this background, germ-cell transcripts in somatic tumours have a long-standing interpretation. Cancer–testis antigens (CTAs), prominently the MAGE, GAGE and CTAG families, are silenced in normal somatic tissue by promoter methylation and become detectable in tumours as that silencing is lost [https://doi.org/10.1002/gcc.20160; https://doi.org/10.1093/nar/gkn673]. Global hypomethylation is one of the oldest recognised epigenetic features of malignancy [https://doi.org/10.1038/301089a0], and promoter demethylation is sufficient to activate cancer-germline genes such as MAGEA1 [https://doi.org/10.1371/journal.pone.0058743], so ectopic germ-cell expression is usually framed as a largely stochastic by-product: promoters that happen to lose methylation happen to be expressed. This reading underpins interest in CTAs as broadly shared immunotherapeutic targets [https://doi.org/10.1016/j.tranon.2019.02.008; https://doi.org/10.1158/0008-5472.CAN-15-2125], an interest sharpened in HNSCC by the activity of checkpoint blockade in recurrent and metastatic disease [https://doi.org/10.1056/NEJMoa1602252]."));
add(P("That framing has been challenged from a different direction. A subset of germ-cell genes expressed in tumours encodes the machinery of meiosis itself: the synaptonemal complex that synapses homologous chromosomes, the meiosis-specific cohesin complex that holds them together, and the recombination and double-strand-break (DSB) factors that execute meiotic pairing. Unlike the MAGE/CTAG families, whose somatic function is largely unknown, these are structurally and enzymatically active components. Meiotic cohesin expressed in mitotic cells generates chromosome instability [https://doi.org/10.1073/pnas.2204071119]; the meiotic protein HORMAD1, when expressed in tumours, has been linked to genomic instability and homologous-recombination deficiency [https://doi.org/10.1158/2159-8290.CD-14-1092; https://doi.org/10.3390/cells12121627] and to the protection of stalled replication forks [https://doi.org/10.1016/j.jbc.2023.105348]; and the concept of “meiomitosis” proposes that partial, mis-scheduled activation of the meiotic programme in somatic cells may itself be oncogenic [https://doi.org/10.1080/15384101.2020.1743902]. Isolated testis-antigen de-repression may therefore be a passenger event, whereas meiotic reactivation may represent a candidate oncogenic programme."));
add(P("Individual meiotic genes are already known to be associated with HPV. Pyeon et al. reported that HPV+ head and neck and cervical cancers overexpress testis-specific genes normally expressed only in meiotic cells, that SYCP2 and TCAM1 are synergistically induced by E6 and E7, and that STAG3 is upregulated in HPV+ head and neck cancer [https://doi.org/10.1158/0008-5472.CAN-06-3619]. SYCP2 deregulation was subsequently proposed as a marker of early-stage HPV+ oropharyngeal carcinoma [https://doi.org/10.1111/cas.12809]; a hypomethylated CpG-island-shore region at SYCP2 correlated with its expression in TCGA HNSCC, with SYCP2 and SMC1B among hypomethylated, overexpressed genes [https://doi.org/10.1186/s13073-017-0419-z]; and SYCP2 and TAF7L emerged from a combined TCGA expression and methylation analysis [https://doi.org/10.3390/ijms231810967]. What has not been established is whether these genes behave as a specific, coordinated programme rather than as independent de-repression events: whether expression is confined to the meiotic machinery as opposed to the MAGE/CTAG antigens, whether the genes are co-regulated, whether expression depends on viral transcription rather than viral DNA, whether it is coupled to promoter methylation across the programme, and whether it resides in malignant cells. These two views have rarely been tested against each other in the same tumours, and HPV+ HNSCC is an informative setting in which to do so. It combines extensive methylome remodelling [https://doi.org/10.1186/gm419; https://doi.org/10.1186/s13073-017-0419-z] with a defined initiating agent whose transcriptional activity can be measured independently of viral DNA [https://doi.org/10.1002/ijc.29649], and well-characterised public cohorts with paired methylation and expression data are available [https://doi.org/10.1038/nature14129]. The two models make different predictions. Stochastic de-repression predicts that germ-cell expression is distributed across germ-cell gene classes in proportion to their promoter methylation, that affected genes vary independently between tumours, and that the phenomenon tracks global hypomethylation rather than any particular viral activity. Programmatic reactivation predicts concentration in one functional class, correlated behaviour among its members, and dependence on the driving stimulus."));
add(P("Here we characterise the transcriptome of HPV+ HNSCC and test these predictions. We asked which genes and pathways distinguish HPV+ from HPV− tumours and whether germ-cell expression is concentrated in the meiotic machinery; whether the affected genes behave as a coordinated module; whether their expression is accompanied by promoter demethylation and tracks viral DNA or viral transcriptional activity; how the immune microenvironment differs between HPV+ and HPV− tumours and whether the meiotic programme resides in malignant cells rather than in that microenvironment; and, in exploratory analyses, whether expression of the leading HPV-associated genes is associated with overall survival. Throughout, the classic MAGE/CTAG antigens serve as an internal comparator that the stochastic model predicts should behave like the meiotic genes."));

// ---------------- METHODS ----------------
add(H1("2. Materials and Methods"));
add(H2("2.1. Data sources and cohort selection"));
add(P("Raw gene-level RNA-sequencing counts for TCGA-HNSC (STAR – Counts workflow) were obtained from the Genomic Data Commons with TCGAbiolinks. Samples were restricted to primary tumours (sample type code 01), and cases without an HPV call were excluded; genomic and clinical records were matched on the first 15 characters of the TCGA barcode. Of 566 RNA-seq samples, 520 were primary tumours and 279 had an HPV call (36 HPV+, 243 HPV−). These 279 tumours form the transcriptomic cohort used for differential expression, enrichment, immune deconvolution and survival analyses. Baseline clinical characteristics were compared between HPV groups with the Wilcoxon rank-sum test for continuous variables and Fisher’s exact or χ² tests for categorical variables (Table 1)."));
add(P("The panel and methylation analyses used a separate processing of the same study: RSEM-normalised expression (Z-scored) and HM450 methylation (β-values) retrieved through the cBioPortal API [https://doi.org/10.1158/2159-8290.CD-12-0095; https://doi.org/10.1126/scisignal.2004088]. Panel-gene coverage and the completeness of p16/in situ hybridisation (ISH) annotations give these analyses smaller sample counts (Table 2). The two TCGA sample sets are therefore not interchangeable, and each analysis below states which it uses."));
add(P("Four further cohorts were analysed (Table 2). GSE65858 [https://doi.org/10.1002/ijc.29649] was used for transcriptional validation and downloaded as a GEO series matrix (Illumina HT-12 v4), with probes collapsed to gene symbols by maximum mean intensity using the GPL10558 annotation. GSE38266 [https://doi.org/10.1186/gm419] provided HM450 data for oropharyngeal tumours only, so that anatomical site was controlled by design; probes were mapped to panel genes through the GPL13534 manifest and restricted to promoter-proximal probes. Two single-cell RNA-seq cohorts were used: GSE181919 [https://doi.org/10.1038/s41467-023-36691-x], which annotates HPV status, tissue type and cell-type identity per barcode and was restricted to primary tumour specimens, and GSE182227 [https://doi.org/10.1038/s41588-023-01357-3], an oropharyngeal cohort deposited without cell-type or malignant-cell labels. In both single-cell cohorts, counts were normalised to 10,000 counts per cell and log-transformed."));
add(H2("2.2. HPV classification"));
add(P("In the transcriptomic cohort, HPV status was taken from the TCGA Network characterisation of HNSCC [https://doi.org/10.1038/nature14129] (cBioPortal study hnsc_tcga_pub), in which viral status was called primarily from HPV transcripts in RNA-sequencing data. In the panel and methylation analyses, HPV status was taken from the p16 and ISH clinical annotations: a tumour was called HPV+ if either assay was positive and was excluded if neither returned a call. Both attributes are recorded at patient level and were mapped to the primary-tumour sample barcode; these calls were audited against the HPV calls supplied by the originating project for samples common to both. GSE65858 records HPV DNA status and HPV transcriptional activity as separate variables, allowing a three-way split into HPV+ tumours with active viral transcription, HPV DNA-positive but transcriptionally silent tumours, and HPV− tumours; samples without a usable call were excluded."));
add(H2("2.3. Differential expression analysis"));
add(P("Differential expression between HPV+ and HPV− tumours was assessed with DESeq2 (v1.52.0) [https://doi.org/10.1186/s13059-014-0550-8] using a negative-binomial generalised linear model with HPV status as the explanatory variable (design ∼ HPV status; reference level HPV−). Size-factor normalisation and dispersion estimation followed the standard DESeq2 workflow, and P values were adjusted with the Benjamini–Hochberg procedure. Genes with FDR < 0.05 and |log~2~FC| > 1 were considered differentially expressed. Because HPV+ tumours were predominantly oropharyngeal, a sensitivity analysis added primary site as a covariate (design ∼ site + HPV status), with sites grouped as oral cavity, oropharynx and other to avoid sparse categories. Variance-stabilised expression was used for principal component analysis and survival modelling."));
add(H2("2.4. Functional enrichment and gene set enrichment analysis"));
add(P("Gene Ontology (GO) biological-process and KEGG pathway over-representation analyses were performed separately for up- and downregulated genes with clusterProfiler (v4.20.0) [https://doi.org/10.1089/omi.2011.0118], using all genes passing expression filtering as the background; terms with adjusted P < 0.05 were considered significant. Gene set enrichment analysis (GSEA) [https://doi.org/10.1073/pnas.0506580102] was performed with clusterProfiler (gseGO) against GO biological-process gene sets, using the full gene ranking by the DESeq2 Wald statistic (duplicate identifiers collapsed by maximum Wald statistic; gene-set size 10–500; Benjamini–Hochberg correction; random seed 123). Because gene symbols in the count matrix were incompletely annotated, identifiers were re-mapped to current HGNC symbols before panel genes were queried. Over-representation of panel genes among upregulated genes was assessed with the hypergeometric test at two significance thresholds; category-level enrichment was assessed with the hypergeometric test with Bonferroni correction across categories, and meiotic categories were compared with the MAGE/CTAG comparator by Fisher’s exact test."));
add(H2("2.5. Gene panel and core module definition"));
add(P("The panel comprises 95 genes in seven categories. Its scope was motivated by the genome-wide enrichment analysis, which identified meiosis as a dominant HPV-associated theme; gene membership, however, was defined from the meiosis literature and CTdatabase family conventions rather than from the differential-expression results, and category assignments were fixed before the analyses below. Six categories cover the germline machinery: synaptonemal complex (n = 10), meiosis-specific cohesin (4), meiotic recombination and DSB factors (23), piRNA/Tudor germline factors (12), cell-cycle regulators with meiosis-specific roles (5) and other germ-cell genes (8). The seventh category, the classic MAGE/CTAG cancer–testis antigen family (33), is the comparator predicted to behave equivalently under stochastic de-repression."));
add(P("Because the discovery, validation, replication and single-cell datasets were generated on different platforms, a single core module was defined so that the same score could be computed in every cohort. A gene was retained only if it was measurable in every cohort: the TCGA-HNSC expression and HM450 methylation matrices, the GSE65858 array after probe collapsing, the GSE38266 HM450 matrix restricted to promoter-proximal probes, and both single-cell count matrices. Expression levels, effect sizes, P values and the HPV contrast were not considered. One core gene, MAJIN, is recorded under its previous HGNC symbol C11orf85 in the deposited single-cell matrices, so both symbols were queried (Supplementary Table {ST:core})."));
add(H2("2.6. Promoter methylation and methylation–expression coupling"));
add(P("In TCGA-HNSC, methylation was summarised per gene as the mean β-value of all probes annotated to the gene in the HM450 manifest. HPV+ versus HPV− differences were tested with the Mann–Whitney U test and Benjamini–Hochberg correction across all testable panel genes. Methylation–expression coupling was assessed per gene as the Spearman correlation between β and expression across samples with both measurements. At sample level, a composite hypomethylation score (mean of Z-scored, sign-inverted β over the core module) and a composite meiotic expression score (mean Z-scored expression over the same genes) were correlated. Replication in GSE38266 was assessed in three ways. The first two used the same gene-level summary as in TCGA (mean β over all annotated probes, 44 genes shared with the discovery cohort): Spearman correlation of per-gene HPV+ minus HPV− methylation differences between the two cohorts, and a sign-concordance binomial test over the same genes, which is insensitive to platform differences in dynamic range. The third was a set-level comparison of mean methylation across the 227 promoter-proximal probes (GPL13534 manifest) mapping to 16 panel genes."));
add(H2("2.7. Module scoring, specificity and coordination"));
add(P("In the bulk cohorts, a module score was the mean Z-scored expression of its member genes. Discrimination between groups was quantified as the area under the receiver-operating-characteristic curve (AUC), with Mann–Whitney P values, for the module score, for each gene and for each panel category; 95% confidence intervals for reported AUCs were obtained with the Hanley–McNeil method from the AUC and group sizes [https://doi.org/10.1148/radiology.143.1.7063747]. In GSE65858, transcriptionally active HPV+ tumours and DNA-positive but transcriptionally silent tumours were each compared with HPV− tumours. Because stochastic de-repression predicts similar behaviour across germ-cell gene classes, specificity was assessed separately within each of the seven panel categories, and the meiotic categories were compared with the MAGE/CTAG comparator. Coordination was quantified as the mean off-diagonal Spearman correlation among module genes within each group. To account for the smaller HPV+ group, an empirical null distribution was generated from 1,000 random HPV− subsets matched to the HPV+ group size, giving an empirical 95% interval and permutation P value for the observed HPV+ coherence."));
add(H2("2.8. Immune-cell deconvolution"));
add(P("Immune-cell composition of the 279 TCGA tumours was estimated with CIBERSORTx [https://doi.org/10.1038/s41587-019-0114-2] and the LM22 signature matrix of 22 immune-cell populations. Raw counts were converted to transcripts per million (TPM), Ensembl identifiers were mapped to HGNC symbols with org.Hs.eg.db (for duplicated symbols, the row with the highest mean expression was retained), and deconvolution was run in relative mode with 100 permutations, without quantile normalisation or batch correction. Fractions were compared between HPV groups with the Wilcoxon rank-sum test and Benjamini–Hochberg correction across all 22 populations (FDR < 0.05). Estimates were validated by Spearman correlation of CD8+ T-cell fractions with variance-stabilised CD8A and CD8B expression and of plasma-cell fractions with IGHM and MS4A1 expression in the TPM matrix supplied to CIBERSORTx. As an exploratory summary, a log~2~ CD8/M2 ratio, log~2~[(CD8 T cells + 10^−6^)/(M2 macrophages + 10^−6^)], was compared between groups with the Wilcoxon test."));
add(H2("2.9. Confounder controls"));
add(P("Three potential confounders of the meiotic signal were addressed. In GSE65858 (virus-active HPV+ vs HPV− tumours), anatomical site was controlled by repeating the analysis in oropharyngeal tumours only, and proliferation, summarised as the mean Z-score of six proliferation-associated genes (MKI67, PCNA, TOP2A, CCNB1, BUB1 and AURKA), was included as a covariate in logistic regression models of HPV status on the core meiotic score, given the functional overlap between meiotic and mitotic cell-cycle processes. In TCGA-HNSC, tumour purity was addressed by merging consensus purity estimates (CPE) [https://doi.org/10.1038/ncomms9971], testing their association with HPV status and with the core meiotic score, and adding purity, and then purity and proliferation, as covariates to a linear model of the core meiotic score on HPV status. p16 expression was not used as a covariate, because p16 status is one of the two assays that define HPV status in the TCGA panel cohort and adjustment would condition on a component of the outcome definition."));
add(H2("2.10. Single-cell analysis"));
add(P("In GSE181919, each deposited cell-type label was re-tested for enrichment of canonical lineage markers relative to all other labelled cell types, and per-cell-type sequencing depth was tabulated to detect compartment-specific dropout. Module activity was scored per cell with the control-gene-binned method of Tirosh et al. [https://doi.org/10.1126/science.aad0501], which corrects the mean expression of a gene set against 50 expression-matched control genes drawn from 25 bins. Two meiotic scores were used: the six-gene core score (MEI1, SMC1B, STAG3, SYCP2, SYCE2, MAJIN) and a four-gene meiosis-specific score (SMC1B, SYCP2, SYCE2, MAJIN) that excludes MEI1 and STAG3, the two core genes detected in lymphocytes (Section 3.11). Scores were also computed for the wider meiotic panel, the MAGE/CTAG comparator and a six-gene proliferation score. Group differences were assessed with the Mann–Whitney test, with rank-biserial AUC as the effect size. Because cells from the same tumour are not independent, a linear mixed model was fitted with patient as a random effect, log-transformed per-cell gene count as a covariate and an HPV × malignant interaction term; in addition, malignant cells were aggregated into one pseudobulk profile per tumour (counts per million; patients contributing fewer than 20 malignant cells excluded). Per-gene detection rates were compared with Fisher’s exact test and Benjamini–Hochberg correction, and the compartment specificity of each core gene was quantified as its detection rate in malignant cells divided by that in the non-malignant compartment with the highest detection rate."));
add(P("Cell-type and malignant-cell assignments were not available for GSE182227 and were derived de novo. Clusters were annotated with the same canonical marker panels, each lineage being required to show enrichment for its own markers relative to all other cells. The epithelial compartment was divided into malignant and normal epithelium using two criteria that were independent of HPV status and of any meiotic gene: the fraction of cells in each epithelial cluster that originated from adjacent-normal tissue, and a per-cell copy-number score inferred from windowed expression along the genome. A cluster was classified as normal only when both criteria agreed. Malignant cells were aggregated into one profile per tumour, and the HPV contrast was tested at tumour level with the Mann–Whitney test and AUC. Proliferation was pre-specified as the principal confounder and included as a covariate in linear models of the per-tumour meiotic score, fitted within each cohort and in the pooled data; robustness was assessed with heteroskedasticity-consistent standard errors and Huber robust regression."));
add(H2("2.11. Exploratory survival analysis"));
add(P("Overall survival (months) and vital status for the 279-tumour transcriptomic cohort were taken from the cBioPortal TCGA-HNSC clinical annotation. The nine most significant HPV-upregulated genes (LOC375196, STAG3, TAF7L, SMC1B, ZFR2, RAD9B, TDRD10, GBX1 and GRIN2C) were analysed. For each gene, a univariable Cox proportional-hazards model (survival v3.8.6) was fitted to variance-stabilised expression scaled to unit variance, so that hazard ratios (HRs) are expressed per standard deviation. Kaplan–Meier curves were drawn for ZFR2, with tumours split at the median. Models were not adjusted for HPV status, stage, smoking or treatment, and P values were not corrected for multiple testing; these analyses were regarded as exploratory."));
add(H2("2.12. Statistical analysis and software"));
add(P("Unless stated otherwise, tests were two-sided and multiple testing was controlled with the Benjamini–Hochberg procedure. Bulk transcriptomic, enrichment and survival analyses were performed in R 4.6.0 with Bioconductor 3.23 (DESeq2, clusterProfiler, enrichplot, org.Hs.eg.db, TCGAbiolinks and survival). Code, processed data and output tables for the TCGA analyses are available at https://github.com/rejoy2004-rgb/TCGA-HNSC-HPV-Transcriptomics."));

// ---------------- RESULTS ----------------
add(H1("3. Results"));
add(H2("3.1. Cohorts and clinical characteristics"));
add(P("The transcriptomic cohort comprised 279 TCGA-HNSC primary tumours, 36 HPV+ and 243 HPV−. HPV+ tumours arose predominantly in the oropharynx (61.1% vs 4.5%; P < 0.001), HPV+ patients were more often male (88.9% vs 70.4%; P = 0.033), and fewer HPV+ patients had died during follow-up (27.8% vs 53.5%; P = 0.007); age, stage and smoking status did not differ significantly (Table 1). Principal component analysis showed partial separation of HPV+ and HPV− tumours on the first two components (22% and 14% of variance; Supplementary Fig. {SF:pca}), indicating that HPV status contributes to, but does not dominate, global transcriptomic variation."));
add(P("Five cohorts were included in the panel-based analyses (Table 2). In TCGA-HNSC, the p16/ISH rule (Section 2.2) identified 44 HPV+ and 81 HPV− tumours with usable promoter methylation data and 41 HPV+ and 80 HPV− tumours with usable expression data; these calls agreed with those of the originating project for all 53 overlapping samples. GSE65858 comprised 35 HPV+ tumours with active viral transcription, 25 HPV DNA-positive tumours without detectable viral transcription and 196 HPV− tumours. GSE38266 contributed 21 HPV+ and 21 HPV− oropharyngeal tumours; 44 panel genes had gene-level methylation in both GSE38266 and the discovery cohort, of which 16 had promoter-proximal probes (227 probes). The single-cell cohorts contributed 23,088 cells from 20 patients (GSE181919) and 16 oropharyngeal tumours, 11 HPV+ and 5 HPV− (GSE182227)."));
